"""The bundled model table (models.json, generated by scripts/sync_models.py from the PopNow model catalog) and local price estimates.

Local estimates only show "about $N" live in the panel as settings change; the amount actually held is the maxChargeUsd from jobs/quote.
The algorithm matches the price estimate on popnow.ai (same price table). Rates come from the catalog's USD table ("usd", decimal strings)
when the bundled entry has one, otherwise from the deprecated credit table at 1 credit = $0.001; all money math uses Decimal, never float.
"""

from __future__ import annotations

import json
import math
import os
from dataclasses import dataclass
from decimal import Decimal
from functools import lru_cache
from typing import Any

from .money import CREDIT_USD, NANO_USD, parse_usd, usd_to_credits

WORKFLOWS = ("render", "animate", "texture")

# When reference seconds are priced separately but the table has no unit price, estimate at this fraction of the output price (errs on the high side)
SEPARATE_RATE_GUESS = Decimal("0.65")


@dataclass(frozen=True)
class ModelSpec:
    raw: dict

    @property
    def model(self) -> str:
        return self.raw["model"]

    @property
    def workflow(self) -> str:
        return self.raw["workflow"]

    @property
    def label(self) -> str:
        return self.raw["label"]

    @property
    def note(self) -> str:
        return self.raw.get("note") or ""

    @property
    def typical_seconds(self) -> int:
        return int(self.raw.get("typicalSeconds") or (180 if self.workflow == "animate" else 60))

    def option(self, key: str) -> dict | None:
        return (self.raw.get("options") or {}).get(key)

    def option_values(self, key: str) -> list:
        """Selectable UI values; duration drops -1 (Smart: the clay clip length must be fixed in advance)"""
        opt = self.option(key)
        if not opt or "values" not in opt:
            return []
        vals = list(opt["values"])
        if key == "duration":
            vals = [v for v in vals if isinstance(v, (int, float)) and v > 0]
        return vals

    def option_default(self, key: str) -> Any:
        opt = self.option(key)
        if not opt:
            return None
        if "default" in opt:
            d = opt["default"]
            if key == "duration" and (not isinstance(d, (int, float)) or d <= 0):
                vals = self.option_values("duration")
                return 5 if 5 in vals else (vals[0] if vals else None)
            return d
        vals = self.option_values(key)
        return vals[0] if vals else None

    def media(self, slot: str) -> dict | None:
        return (self.raw.get("media") or {}).get(slot)

    def token(self, field: str, index: int) -> str | None:
        """How the prompt names the index-th input (1-based); None when the model has no convention"""
        fmt = (self.raw.get("tokens") or {}).get(field)
        if not fmt:
            return None
        return fmt.replace("{index}", str(index))

    @property
    def clip_rules(self) -> dict:
        """Clay clip length and size limits: min / max seconds, minSide pixels"""
        rules = dict(self.raw.get("clip") or {})
        iv = (self.raw.get("usd") or self.raw.get("credits") or {}).get("inputVideo") or {}
        if "min" not in rules and iv.get("minSeconds"):
            rules["min"] = iv["minSeconds"]
        if "max" not in rules and iv.get("maxTotalSeconds"):
            rules["max"] = iv["maxTotalSeconds"]
        return rules

    @property
    def uses_duration_option(self) -> bool:
        return bool(self.option_values("duration"))

    @property
    def max_refs(self) -> int:
        """How many reference images fit besides the clay render / structure pass"""
        refs = self.media("refs")
        if not refs:
            return 0
        n = refs["max"]
        st = self.media("structure")
        if st and st["field"] == refs["field"]:
            n -= 2  # clay render + possibly one structure pass
        return max(0, min(n, 4))


@lru_cache(maxsize=1)
def _load() -> dict:
    with open(os.path.join(os.path.dirname(__file__), "models.json"), encoding="utf-8") as f:
        return json.load(f)


def all_models() -> list[ModelSpec]:
    return [ModelSpec(m) for m in _load()["models"]]


def models_for(workflow: str) -> list[ModelSpec]:
    return [m for m in all_models() if m.workflow == workflow]


def get(model: str) -> ModelSpec | None:
    for m in all_models():
        if m.model == model:
            return m
    return None


def snapshot() -> str:
    return str(_load().get("snapshot") or "")


# ---------------- local estimates ----------------


@dataclass(frozen=True)
class Estimate:
    usd: Decimal
    approx: bool

    @property
    def credits(self) -> int:
        """Deprecated: the estimate in whole credits (1 credit = $0.001), rounded up as the old panel showed it"""
        return max(1, usd_to_credits(self.usd))


def _up(x: Decimal) -> Decimal:
    """Round up to the smallest billed amount ($0.000000001)"""
    return x.quantize(NANO_USD, rounding="ROUND_CEILING")


def _rate(value: Any, scale: Decimal) -> Decimal | None:
    """A rate from the price table: a USD string (scale 1) or a deprecated credit number (scale $0.001)"""
    if isinstance(value, str):
        d = parse_usd(value)
        return d * scale if d is not None else None
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        # str() keeps the table's own digits (10.97 stays 10.97) instead of the float's binary expansion
        return Decimal(str(value)) * scale
    return None


def _price_table(spec: ModelSpec) -> tuple[dict, Decimal] | None:
    """The USD table when the bundled entry has one, otherwise the deprecated credit table and its scale"""
    usd = spec.raw.get("usd")
    if usd and parse_usd(str(usd.get("perUnit", ""))) is not None:
        return usd, Decimal(1)
    credits = spec.raw.get("credits")
    if credits:
        return credits, CREDIT_USD
    return None


def _input_video_quantity(spec: dict, output_seconds: float, segments: list[float | None]) -> int:
    lo = spec.get("minSeconds") or 0
    hi = spec.get("maxTotalSeconds")
    total = 0
    for s in segments:
        if s is None or s <= 0:
            if hi:
                return int(hi)
            total += math.ceil(lo)
            continue
        total += math.ceil(round(max(s, lo) * 1000) / 1000)
    by_out = spec.get("minByOutput") or {}
    if by_out and output_seconds > 0:
        out = round(output_seconds)
        keys = [int(k) for k in by_out]
        top = max(keys) if keys else 0
        floor = by_out.get(str(out))
        if floor is None and top and out > top:
            floor = by_out.get(str(top))
        total = max(total, floor or 0)
    if hi and total > hi:
        total = int(hi)
    return int(total)


def estimate(spec: ModelSpec, input: dict, *, clip_seconds: list[float | None] | None = None, output_seconds: float | None = None) -> Estimate | None:
    """Estimate the USD price of this request from the price table. input is the input to be submitted (missing fields use the model defaults)"""
    found = _price_table(spec)
    if found is None:
        return None
    table, scale = found
    eff: dict[str, Any] = {}
    for key, opt in (spec.raw.get("options") or {}).items():
        if "default" in opt:
            eff[opt["field"]] = opt["default"]
    eff.update(input)
    presence = (spec.raw.get("pricing") or {}).get("presenceFields") or {}

    def s(v: Any) -> str:
        if isinstance(v, bool):
            return "true" if v else "false"
        return str(v).lower()

    def extra(k: str) -> Any:
        f = presence.get(k)
        if f:
            v = eff.get(f)
            return bool(v) if not isinstance(v, list) else len(v) > 0
        if k == "with_video":
            return any(("video" in n) and (len(v) > 0 if isinstance(v, list) else bool(v)) for n, v in eff.items())
        return False

    def matches(when: dict) -> bool:
        for k, want in when.items():
            if k == "*":
                if not any(s(v) == s(want) for v in eff.values()):
                    return False
            elif s(eff[k] if k in eff else extra(k)) != s(want):
                return False
        return True

    rules = [r for r in table.get("rules") or [] if matches(r.get("when") or {})]
    rules.sort(key=lambda r: -len(r.get("when") or {}))
    per_unit = _rate(rules[0]["perUnit"] if rules else table["perUnit"], scale)
    if per_unit is None:
        return None
    unit = table.get("unit")
    approx = False
    if unit == "per_second":
        d = eff.get("duration_seconds")
        if output_seconds and output_seconds > 0 and not isinstance(d, (int, float)):
            qty = Decimal(str(output_seconds))
        elif isinstance(d, (int, float)) and d > 0:
            qty = Decimal(str(d))
        else:
            qty, approx = Decimal(5), True
        iv = table.get("inputVideo")
        ref = eff.get(iv["field"]) if iv else None
        clips = len(ref) if isinstance(ref, list) else (1 if ref else 0)
        if iv and clips:
            segs = list(clip_seconds or [])[:clips] + [None] * max(0, clips - len(clip_seconds or []))
            if any(x is None or x <= 0 for x in segs):
                approx = True
            ref_qty = Decimal(_input_video_quantity(iv, float(qty), segs))
            rate = iv.get("rate")
            if not rate:
                return Estimate(_up(per_unit * (qty + ref_qty)), approx)
            known_rate = _rate(rate.get("perUnit"), scale)
            ref_unit = known_rate if known_rate is not None else per_unit * SEPARATE_RATE_GUESS
            return Estimate(_up(per_unit * qty + ref_unit * ref_qty), approx or known_rate is None)
        return Estimate(_up(per_unit * qty), approx)
    if unit == "per_image":
        qty = eff.get("num_outputs") or 1
        return Estimate(_up(per_unit * Decimal(str(qty))), approx)
    # per_request and the like: one unit per request
    return Estimate(_up(per_unit), approx)


# ---------------- aspect ratio ----------------


def _ratio(v: str) -> float | None:
    try:
        a, b = v.split(":")
        return float(a) / float(b)
    except (ValueError, ZeroDivisionError):
        return None


def closest_aspect(values: list, width: int, height: int) -> str | None:
    """Pick the model aspect ratio closest to width:height (auto / adaptive are ignored)"""
    if not values or width <= 0 or height <= 0:
        return None
    target = math.log(width / height)
    best, best_d = None, 1e9
    for v in values:
        if not isinstance(v, str):
            continue
        r = _ratio(v)
        if r is None:
            continue
        d = abs(math.log(r) - target)
        if d < best_d:
            best, best_d = v, d
    return best
